import SimplexNoise from 'simplex-noise';
const noise = new SimplexNoise();

export function generateChunk(cx:number,cy:number,H:number[]){
 let tiles=[];
 let n = noise.noise2D(cx*0.1,cy*0.1);

 let biome = 'plains';
 if(H[0] > 0.5) biome='forest';
 if(H[6] > 0.5) biome='desert';
 if(H[5] > 0.7) biome='ruins';

 for(let x=0;x<32;x++){
  for(let y=0;y<32;y++){
   tiles.push({x,y,type:biome});
  }
 }

 return { id:`${cx}_${cy}`, tiles, biome, resources:Math.random()*100 };
}

Dynamic Expansion Trigger.Code:
export function checkExpansion(playerPos,loadedChunks){
 const {cx,cy} = playerPos;
 let needed=[];

 for(let dx=-1;dx<=1;dx++){
  for(let dy=-1;dy<=1;dy++){
   let key=`${cx+dx}_${cy+dy}`;
   if(!loadedChunks.has(key)){
    needed.push({x:cx+dx,y:cy+dy});
   }
  }
 }
 return needed;
}

World Manager.Code:
const chunks = new Map();

export function updateWorld(player,H){
 const needed = checkExpansion(player,chunks);

 needed.forEach(pos=>{
  const chunk = generateChunk(pos.x,pos.y,H);
  chunks.set(chunk.id,chunk);
 });

 return chunks;
}

